}], "facturas_ing": [], "costos": [], "ingresos_extras": [], "total_egr": 5000000.0, "total_ing": 0, "net": -5000000.0}, {"week_start": "2026-10-19", "week_end": "2026-10-25", "label": "19/10 – 25/10", "mes": "October 2026", "cheques": [{"fecha": "2026-10-23", "emitido_a": "BAHIA CLIMA SA", "monto": 547319.78, "estado": "pendiente", "n_cheque": "00000974"}, {"fecha": "2026-10-25", "emitido_a": "SERVICIOS MEDICOS SRL", "monto": 8230675.35, "estado": "pendiente", "n_cheque": "00000978"}], "facturas_ing": [], "costos": [], "ingresos_extras": [], "total_egr": 8777995.129999999, "total_ing": 0, "net": -8777995.129999999}, {"week_start": "2026-10-26", "week_end": "2026-11-01", "label": "26/10 – 01/11", "mes": "October 2026", "cheques": [{"fecha": "2026-10-31", "emitido_a": "UNIVERSIDAD NACIONAL DE CORDOBA", "monto": 1209733.46, "estado": "pendiente", "n_cheque": "00000893"}, {"fecha": "2026-10-31", "emitido_a": "SOCIEDAD DE BENEFICENCIA HOSPITAL ITALIA", "monto": 6614405.95, "estado": "pendiente", "n_cheque": "00000951"}, {"fecha": "2026-10-31", "emitido_a": "CLINICA PRIVADA INTEGRAL DE PSIQUIATRIA", "monto": 3106142.25, "estado": "pendiente", "n_cheque": "00000803"}, {"fecha": "2026-10-31", "emitido_a": "SANATORIO DEL SALVADOR PRIVADO SA", "monto": 3579372.14, "estado": "pendiente", "n_cheque": "00000919"}, {"fecha": "2026-10-31", "emitido_a": "SOCIEDAD DE BENEFICENCIA HOSPITAL ITALIA", "monto": 10664482.56, "estado": "pendiente", "n_cheque": "00000884"}, {"fecha": "2026-10-31", "emitido_a": "ECCO SA", "monto": 3787143.14, "estado": "pendiente", "n_cheque": "00000900"}, {"fecha": "2026-10-31", "emitido_a": "GPAL BIOQUIMICA CLINICA SAS", "monto": 1272742.48, "estado": "pendiente", "n_cheque": "00000937"}, {"fecha": "2026-10-31", "emitido_a": "AMPARAR S.R.L.", "monto": 4245212.64, "estado": "pendiente", "n_cheque": "00000826"}, {"fecha": "2026-10-31", "emitido_a": "CE MO SA", "monto": 871101.34, "estado": "pendiente", "n_cheque": "00000932"}, {"fecha": "2026-10-31", "emitido_a": "FIDEICOMISO CHUTRO", "monto": 4734073.04, "estado": "pendiente", "n_cheque": "00000671"}, {"fecha": "2026-10-31", "emitido_a": "FIDEICOMISO CHUTRO", "monto": 934736.06, "estado": "pendiente", "n_cheque": "00000891"}, {"fecha": "2026-10-31", "emitido_a": "CIPREM S.R.L.", "monto": 3059072.18, "estado": "pendiente", "n_cheque": "00000947"}, {"fecha": "2026-10-31", "emitido_a": "PABLO GABRIEL MIGLIERINI", "monto": 4677500.0, "estado": "pendiente", "n_cheque": "00000784"}], "facturas_ing": [], "costos": [{"descripcion": "Alquiler oficina", "fecha": "2026-11-01", "monto": 850000.0, "tipo": "Fijo", "notas": ""}], "ingresos_extras": [], "total_egr": 49605717.24, "total_ing": 0, "net": -49605717.24}, {"week_start": "2026-11-02", "week_end": "2026-11-08", "label": "02/11 – 08/11", "mes": "November 2026", "cheques": [{"fecha": "2026-11-05", "emitido_a": "TOMAS FRANCISCO RAMOS", "monto": 1375000.0, "estado": "pendiente", "n_cheque": "00000961"}], "facturas_ing": [], "costos": [], "ingresos_extras": [], "total_egr": 1375000.0, "total_ing": 0, "net": -1375000.0}, {"week_start": "2026-11-09", "week_end": "2026-11-15", "label": "09/11 – 15/11", "mes": "November 2026", "cheques": [], "facturas_ing": [], "costos": [], "ingresos_extras": [], "total_egr": 0, "total_ing": 0, "net": 0}]}}</script>
<script>
const STATE = JSON.parse(document.getElementById("state-data").textContent);
const STATUS_LABELS = STATE.status_labels;
const ACTIVE = ["pendiente", "en_proceso_deposito"];
const BRAND = { primary: "#1a1ac7", accent: "#22c4ec", danger: "#c0392b", success: "#0a8a5e" };
const fmtARS = new Intl.NumberFormat("es-AR", {style:"currency", currency:"ARS", maximumFractionDigits:0});
const fmtN = new Intl.NumberFormat("es-AR", {maximumFractionDigits:0});
const fmtPct = (n) => (n==null||isNaN(n))?"—":new Intl.NumberFormat("es-AR",{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)+"%";
function fmtDate(iso) { if(!iso) return "—"; const [y,m,d]=iso.split("-"); return `${d}/${m}/${y}`; }
function fmtDateShort(iso) { if(!iso) return "—"; const [,m,d]=iso.split("-"); return `${d}/${m}`; }
function escapeHtml(s) { if(s==null) return ""; return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])); }
function todayISO() { return STATE.today; }
function addDays(iso, n) { const d=new Date(iso+"T12:00:00"); d.setDate(d.getDate()+n); return d.toISOString().slice(0,10); }
function diffDays(a,b) { return Math.round((new Date(b+"T12:00:00")-new Date(a+"T12:00:00"))/86400000); }
window.toggleCollapse = (id) => document.getElementById(id).classList.toggle("expanded");
function activateTab(tabId) {
  document.querySelectorAll(".tab").forEach(x => x.classList.remove("active"));
  document.querySelectorAll("section").forEach(x => x.classList.remove("active"));
  const btn = document.querySelector(`.tab[data-tab="${tabId}"]`);
  const sec = document.getElementById(tabId);
  if (btn) btn.classList.add("active");
  if (sec) sec.classList.add("active");
}
document.querySelectorAll(".tab").forEach(t => t.addEventListener("click", () => activateTab(t.dataset.tab)));
// Auto-activar pestaña si viene desde INICIO.php (Cash Flow card)
(function() {
  const stored = sessionStorage.getItem("fb_tab");
  if (stored) { sessionStorage.removeItem("fb_tab"); activateTab(stored); }
  else if (location.hash === "#cashflow") { activateTab("cashflow"); }
})();

function statusChipClass(s) {
  if (s==="acreditado") return "success";
  if (s==="rechazado") return "danger";
  if (s==="anulado") return "warn";
  if (s==="en_proceso_deposito") return "accent";
  return "primary";
}

function renderCheques() {
  const filter = document.getElementById("check-filter").value;
  const search = document.getElementById("check-search").value.toLowerCase().trim();
  let list = STATE.cheques.slice();
  if (filter !== "all") list = list.filter(c => c.ESTADO === filter);
  if (search) list = list.filter(c =>
    (c.BENEFICIARIO||"").toLowerCase().includes(search) ||
    (c.N_CHEQUE||"").toLowerCase().includes(search) ||
    (c.BANCO||"").toLowerCase().includes(search));
  list.sort((a,b) => (a.FECHA_PAGO||"").localeCompare(b.FECHA_PAGO||""));
  const tb = document.getElementById("check-totalbar");
  if (!list.length) {
    tb.innerHTML = `<div class="item"><div class="lbl">Sin resultados</div></div>`;
  } else {
    const total = list.reduce((s,c) => s+(+c.IMPORTE||0), 0);
    const pend = list.filter(c => c.ESTADO==="pendiente");
    const ep = list.filter(c => c.ESTADO==="en_proceso_deposito");
    const acr = list.filter(c => c.ESTADO==="acreditado");
    let parts = [`<div class="item"><div class="lbl">${list.length} cheques</div><div class="val">${fmtARS.format(total)}</div></div>`];
    if (pend.length) parts.push(`<div class="sep"></div><div class="item"><div class="lbl">Pendientes</div><div class="val danger">${pend.length} · ${fmtARS.format(pend.reduce((s,c)=>s+(+c.IMPORTE||0),0))}</div></div>`);
    if (ep.length) parts.push(`<div class="sep"></div><div class="item"><div class="lbl">En depósito</div><div class="val accent">${ep.length} · ${fmtARS.format(ep.reduce((s,c)=>s+(+c.IMPORTE||0),0))}</div></div>`);
    if (acr.length) parts.push(`<div class="sep"></div><div class="item"><div class="lbl">Acreditados</div><div class="val success">${acr.length} · ${fmtARS.format(acr.reduce((s,c)=>s+(+c.IMPORTE||0),0))}</div></div>`);
    tb.innerHTML = parts.join("");
  }
  const tbody = document.querySelector("#check-table tbody");
  if (!list.length) { tbody.innerHTML = `<tr><td colspan="7" class="empty">Sin cheques.</td></tr>`; return; }
  tbody.innerHTML = list.map(c => {
    const sCl = statusChipClass(c.ESTADO);
    return `<tr><td>${escapeHtml(c.N_CHEQUE)}</td><td>${escapeHtml(c.BANCO||"—")}</td><td>${escapeHtml(c.BENEFICIARIO||"—")}</td><td>${fmtDate(c.FECHA_PAGO)}</td><td class="num">${fmtARS.format(+c.IMPORTE||0)}</td><td><span class="chip ${sCl}">${STATUS_LABELS[c.ESTADO]||c.ESTADO}</span></td><td><span class="chip">${escapeHtml(c.ESTADO_BANCO||"")}</span></td></tr>`;
  }).join("");
}
document.getElementById("check-filter").addEventListener("change", renderCheques);
document.getElementById("check-search").addEventListener("input", renderCheques);
document.getElementById("btn-check-reset").addEventListener("click", () => {
  document.getElementById("check-filter").value = "all";
  document.getElementById("check-search").value = "";
  renderCheques();
});

function renderGastos() {
  const fM = document.getElementById("expense-filter-method").value;
  const fS = document.getElementById("expense-filter-status").value;
  let list = STATE.gastos.slice();
  if (fM !== "all") list = list.filter(x => x.METODO === fM);
  if (fS !== "all") list = list.filter(x => x.ESTADO === fS);
  list.sort((a,b) => (a.FECHA||"").localeCompare(b.FECHA||""));
  document.getElementById("expense-count").textContent = `${list.length} gastos`;
  const tbody = document.querySelector("#expense-table tbody");
  if (!list.length) { tbody.innerHTML = `<tr><td colspan="6" class="empty">Sin gastos.</td></tr>`; return; }
  tbody.innerHTML = list.map(x => {
    const sCh = x.ESTADO === "pagado" ? `<span class="chip success">Pagado</span>` : `<span class="chip warn">Proyectado</span>`;
    return `<tr><td>${fmtDate(x.FECHA)}</td><td>${escapeHtml(x.CONCEPTO)}</td><td><span class="chip">${escapeHtml(x.METODO)}</span></td><td><span class="chip">${escapeHtml(x.CATEGORIA)}</span></td><td class="num" style="color:var(--danger)">−${fmtARS.format(+x.MONTO||0)}</td><td>${sCh}</td></tr>`;
  }).join("");
  const today = todayISO(); const horizon = addDays(today, 30);
  const upc = STATE.gastos.filter(x => x.ESTADO==="proyectado" && x.FECHA>=today && x.FECHA<=horizon);
  const byMethod = {}; let totalUpc = 0;
  upc.forEach(x => { byMethod[x.METODO] = (byMethod[x.METODO]||0)+(+x.MONTO||0); totalUpc += (+x.MONTO||0); });
  const cs = document.getElementById("expense-summary");
  if (!upc.length) { cs.innerHTML = `<div class="mini-card"><div class="label">Sin gastos próximos</div><div class="value">—</div></div>`; }
  else {
    const t = `<div class="mini-card danger"><div class="label">Total 30 días</div><div class="value">${fmtARS.format(totalUpc)}</div></div>`;
    cs.innerHTML = t + Object.entries(byMethod).map(([m,v]) => `<div class="mini-card"><div class="label">${escapeHtml(m)}</div><div class="value">${fmtARS.format(v)}</div></div>`).join("");
  }
}
function buildExpenseFilterOptions() {
  const sel = document.getElementById("expense-filter-method");
  const metodos = [...new Set(STATE.gastos.map(g => g.METODO))].filter(Boolean).sort();
  sel.innerHTML = `<option value="all">Todos los métodos</option>` + metodos.map(m => `<option value="${escapeHtml(m)}">${escapeHtml(m)}</option>`).join("");
}
document.getElementById("expense-filter-method").addEventListener("change", renderGastos);
document.getElementById("expense-filter-status").addEventListener("change", renderGastos);

function renderInversiones() {
  const today = todayISO();
  const list = STATE.inversiones.slice().sort((a,b) => (a.FECHA_VTO||"").localeCompare(b.FECHA_VTO||""));
  const active = list.filter(i => i.FECHA_VTO >= today).length;
  document.getElementById("invest-count").textContent = `${active} activas / ${list.length} total`;
  const tbody = document.querySelector("#invest-table tbody");
  if (!list.length) { tbody.innerHTML = `<tr><td colspan="8" class="empty">Sin inversiones.</td></tr>`; return; }
  tbody.innerHTML = list.map(inv => {
    const isActive = inv.FECHA_VTO >= today;
    const dias = inv.FECHA_INICIO ? diffDays(inv.FECHA_INICIO, inv.FECHA_VTO) : 0;
    const monto = +inv.MONTO || 0;
    const tna = +inv.TNA || 0;
    const est = (tna>0 && dias>0) ? monto * (1 + (tna/100)*(dias/365)) : monto;
    return `<tr><td><span class="chip accent">${escapeHtml(inv.TIPO)}</span></td><td>${escapeHtml(inv.PLATAFORMA||"—")}</td><td>${fmtDate(inv.FECHA_INICIO)}</td><td>${fmtDate(inv.FECHA_VTO)}</td><td class="num">${fmtARS.format(monto)}</td><td class="num">${tna?fmtPct(tna):"—"}</td><td class="num">${fmtARS.format(est)}</td><td><span class="chip ${isActive?"success":""}">${isActive?"Activa":"Vencida"}</span></td></tr>`;
  }).join("");
}

function renderMovimientos() {
  const list = STATE.movimientos.slice().sort((a,b) => (a.FECHA||"").localeCompare(b.FECHA||""));
  document.getElementById("movement-count").textContent = `${list.length} movimientos`;
  const tbody = document.querySelector("#movement-table tbody");
  if (!list.length) { tbody.innerHTML = `<tr><td colspan="4" class="empty">Sin movimientos.</td></tr>`; return; }
  tbody.innerHTML = list.map(m => {
    const ch = m.TIPO === "ingreso" ? `<span class="chip success">Ingreso</span>` : `<span class="chip warn">Egreso</span>`;
    return `<tr><td>${fmtDate(m.FECHA)}</td><td>${ch}</td><td>${escapeHtml(m.CONCEPTO)}</td><td class="num">${fmtARS.format(+m.MONTO||0)}</td></tr>`;
  }).join("");
}

// === Buffer de saldos pendientes (cambios in-memory que aun no se guardaron al CSV) ===
let saldosPendientes = [];

function renderSaldos() {
  const combined = STATE.saldos.slice();
  saldosPendientes.forEach(p => {
    const idx = combined.findIndex(s => s.FECHA === p.FECHA && s.CUENTA === p.CUENTA);
    if (idx >= 0) combined[idx] = { ...combined[idx], ...p, _pendiente: true };
    else combined.push({ ...p, _pendiente: true });
  });
  combined.sort((a,b) => (b.FECHA||"").localeCompare(a.FECHA||""));
  document.getElementById("balance-count").textContent = `${combined.length} registros`;
  const tbody = document.querySelector("#balance-table tbody");
  if (!combined.length) { tbody.innerHTML = `<tr><td colspan="5" class="empty">Sin saldos cargados. Usá el formulario de arriba.</td></tr>`; return; }
  tbody.innerHTML = combined.slice(0,100).map(b => {
    const origen = b._pendiente
      ? `<span class="chip warn">Pendiente</span>`
      : `<span class="chip">${escapeHtml(b.ARCHIVO_ORIGEN||"csv")}</span>`;
    return `<tr><td>${fmtDate(b.FECHA)}</td><td>${escapeHtml(b.CUENTA)}</td><td class="num">${fmtARS.format(+b.SALDO||0)}</td><td>${escapeHtml(b.NOTAS||"")}</td><td>${origen}</td></tr>`;
  }).join("");
  const pendBlock = document.getElementById("saldo-pending");
  if (saldosPendientes.length > 0) {
    pendBlock.style.display = "block";
    document.getElementById("saldo-pending-count").textContent = saldosPendientes.length;
  } else {
    pendBlock.style.display = "none";
  }
}

function buildSaldoCuentas() {
  const sel = document.getElementById("saldo-cuenta");
  sel.innerHTML = STATE.cuentas.map(c =>
    `<option value="${escapeHtml(c.id)}">${escapeHtml(c.nombre)}${c.banco ? " - " + escapeHtml(c.banco) : ""}</option>`
  ).join("");
  document.getElementById("saldo-fecha").value = STATE.today;
}

document.getElementById("form-saldo").addEventListener("submit", (e) => {
  e.preventDefault();
  const fecha = document.getElementById("saldo-fecha").value;
  const cuenta = document.getElementById("saldo-cuenta").value;
  const monto = parseFloat(document.getElementById("saldo-monto").value);
  const notas = document.getElementById("saldo-notas").value.trim();
  if (!fecha || isNaN(monto)) { alert("Falta fecha o monto"); return; }
  saldosPendientes = saldosPendientes.filter(p => !(p.FECHA === fecha && p.CUENTA === cuenta));
  saldosPendientes.push({ FECHA: fecha, CUENTA: cuenta, SALDO: monto, NOTAS: notas });
  document.getElementById("form-saldo").reset();
  document.getElementById("saldo-fecha").value = STATE.today;
  renderSaldos();
});

document.getElementById("btn-descartar-cambios").addEventListener("click", () => {
  if (!confirm("¿Descartar los cambios pendientes?")) return;
  saldosPendientes = [];
  renderSaldos();
});

document.getElementById("btn-descargar-saldos").addEventListener("click", () => {
  const map = {};
  STATE.saldos.forEach(s => { map[`${s.FECHA}|${s.CUENTA}`] = s; });
  saldosPendientes.forEach(p => { map[`${p.FECHA}|${p.CUENTA}`] = p; });
  const all = Object.values(map).sort((a,b) => (a.FECHA||"").localeCompare(b.FECHA||""));
  const lines = ["fecha,cuenta,saldo_apertura,notas"];
  all.forEach(s => {
    const fecha = s.FECHA || "";
    const cuenta = (s.CUENTA || "").replace(/,/g, " ");
    const saldo = (+s.SALDO || 0);
    const notas = (s.NOTAS || "").replace(/,/g, " ").replace(/\r?\n/g, " ");
    lines.push(`${fecha},${cuenta},${saldo},${notas}`);
  });
  const csv = lines.join("\n");
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "saldos.csv";
  a.click();
  URL.revokeObjectURL(url);
  alert("Descargado.\n\n1) Movelo a 1_inputs/saldos/ (reemplaza el viejo).\n2) Doble clic en actualizar.bat.");
});

let chart30, chart90;
function getMinBalanceTotal() { return STATE.cuentas.reduce((s,a) => s + (a.min_balance||0), 0); }
function suggestInvestment(days, amount) {
  if (days<=0) return null;
  let s = "Caución 1-7 días";
  if (days>=180) s = "LECAP larga o bono corto";
  else if (days>=90) s = "LECAP corta o plazo fijo pre-cancelable";
  else if (days>=30) s = "Plazo fijo 30 días o caución renovable";
  else if (days>=7) s = "Caución 7-30 días";
  const diff = ((STATE.params.caucionRate||0)-(STATE.params.fciRate||0))/100;
  return { suggestion: s, extra: amount*diff*(days/365) };
}

function renderDashboard() {
  const today = todayISO();
  const apertura = STATE.points30.length ? STATE.points30[0].balance - (STATE.points30[0].inflow||0) + (STATE.points30[0].outflow||0) : 0;
  const sortedB = STATE.saldos.slice().sort((a,b) => (b.FECHA||"").localeCompare(a.FECHA||""));
  const latestDate = sortedB.length ? sortedB[0].FECHA : null;
  document.getElementById("kpi-balance").textContent = fmtARS.format(apertura);
  document.getElementById("kpi-balance-sub").textContent = latestDate ? `Apertura desde ${fmtDate(latestDate)}` : "Sin saldos";
  document.getElementById("projection-hint").textContent = latestDate ? `Última carga: ${fmtDate(latestDate)}` : "Cargá un saldo en la pestaña Saldos";

  const activeInv = STATE.inversiones.filter(i => i.FECHA_VTO >= today);
  const invTotal = activeInv.reduce((s,i) => s+(+i.MONTO||0), 0);
  document.getElementById("kpi-invest").textContent = fmtARS.format(invTotal);
  document.getElementById("kpi-invest-sub").textContent = `${activeInv.length} posiciones`;

  const active = STATE.cheques.filter(c => ACTIVE.includes(c.ESTADO));
  const cR = active.filter(c => c.TIPO==="recibido").reduce((s,c) => s+(+c.IMPORTE||0), 0);
  const cE = active.filter(c => c.TIPO==="emitido").reduce((s,c) => s+(+c.IMPORTE||0), 0);
  document.getElementById("kpi-checks").textContent = fmtARS.format(cR-cE);
  document.getElementById("kpi-checks-sub").textContent = `+${fmtARS.format(cR)} / −${fmtARS.format(cE)}`;

  const horizon = addDays(today, 30);
  const upcExp = STATE.gastos.filter(x => x.ESTADO==="proyectado" && x.FECHA>=today && x.FECHA<=horizon);
  const eT = upcExp.reduce((s,x) => s+(+x.MONTO||0), 0);
  document.getElementById("kpi-expenses").textContent = fmtARS.format(eT);
  document.getElementById("kpi-expenses-sub").textContent = `${upcExp.length} gastos`;
  document.getElementById("kpi-total").textContent = fmtARS.format(apertura + invTotal + (cR-cE));

  drawChart30();
  drawChart90();
  renderAlerts();
  renderUpcoming();
  renderSimulador();

  document.getElementById("last-update").textContent = STATE.info_corrida.fecha ? `Generado: ${STATE.info_corrida.fecha}` : "";
}

function drawChart30() {
  const ctx = document.getElementById("chart-30");
  const labels = STATE.points30.map(p => fmtDateShort(p.date));
  const min = getMinBalanceTotal();
  const buffer = STATE.params.buffer || 0;
  if (chart30) chart30.destroy();
  const cctx = ctx.getContext("2d");
  const grad = cctx.createLinearGradient(0,0,0,320);
  grad.addColorStop(0,"rgba(26,26,199,0.20)"); grad.addColorStop(1,"rgba(34,196,236,0.05)");
  chart30 = new Chart(ctx, { type:"line", data: {
    labels,
    datasets: [
      { label:"Saldo cierre", data: STATE.points30.map(p => p.balance), borderColor: BRAND.primary, backgroundColor: grad, fill:true, tension:0.25, pointRadius:2, pointBackgroundColor: BRAND.primary, borderWidth:2.5 },
      { label:"Mínimo", data: STATE.points30.map(() => min), borderColor: BRAND.danger, borderDash:[4,4], pointRadius:0, borderWidth:1.5, fill:false },
      { label:"Umbral", data: STATE.points30.map(() => min+buffer), borderColor: BRAND.success, borderDash:[2,4], pointRadius:0, borderWidth:1.5, fill:false }
    ]
  }, options: { responsive:true, maintainAspectRatio:false,
    plugins: { legend:{display:false}, tooltip:{callbacks:{label:c=>c.dataset.label+": "+fmtARS.format(c.raw)}} },
    scales: { y:{ticks:{callback:v=>fmtN.format(v),color:"#5b6385"},grid:{color:"rgba(17,22,61,0.06)"}}, x:{ticks:{maxRotation:0,autoSkip:true,maxTicksLimit:12,color:"#5b6385"},grid:{display:false}} }
  }});
}
function drawChart90() {
  const weeks = [];
  for (let i=0;i<STATE.points90.length;i+=7) {
    const slice = STATE.points90.slice(i, i+7); if (!slice.length) continue;
    weeks.push({ label: fmtDateShort(slice[0].date), avg: slice.reduce((s,p) => s+p.balance, 0)/slice.length, min: Math.min(...slice.map(p=>p.balance)), max: Math.max(...slice.map(p=>p.balance)) });
  }
  const ctx = document.getElementById("chart-90"); if (chart90) chart90.destroy();
  const min = getMinBalanceTotal();
  chart90 = new Chart(ctx, { type:"bar", data: {
    labels: weeks.map(w => w.label),
    datasets: [
      { type:"line", label:"Mín. ref", data: weeks.map(() => min), borderColor: BRAND.danger, borderDash:[4,4], pointRadius:0, borderWidth:1.5, fill:false },
      { label:"Mín semana", data: weeks.map(w => w.min), backgroundColor:"rgba(192,57,43,0.55)", borderRadius:3 },
      { label:"Promedio", data: weeks.map(w => w.avg), backgroundColor:"rgba(26,26,199,0.75)", borderRadius:3 },
      { label:"Máx semana", data: weeks.map(w => w.max), backgroundColor:"rgba(34,196,236,0.75)", borderRadius:3 }
    ]
  }, options: { responsive:true, maintainAspectRatio:false,
    plugins: { legend:{position:"bottom", labels:{boxWidth:10,font:{size:11},color:"#5b6385"}}, tooltip:{callbacks:{label:c=>c.dataset.label+": "+fmtARS.format(c.raw)}} },
    scales: { y:{ticks:{callback:v=>fmtN.format(v),color:"#5b6385"},grid:{color:"rgba(17,22,61,0.06)"}}, x:{ticks:{color:"#5b6385"},grid:{display:false}} }
  }});
}

function renderAlerts() {
  const c = document.getElementById("alerts-container");
  const summary = document.getElementById("alerts-summary");
  const panel = document.getElementById("alerts-panel");
  if (!STATE.saldos.length) {
    c.innerHTML = `<div class="alert info"><span class="icon">i</span><div>No hay saldos cargados. Cargá uno en la pestaña <strong>Saldos</strong> o pegá un CSV en <code>1_inputs/saldos/</code>.</div></div>`;
    summary.innerHTML = `<span class="badge info">setup pendiente</span>`;
    panel.classList.add("expanded"); return;
  }
  const items = []; let dangerCount=0, warnCount=0, successCount=0, infoCount=0;
  if (STATE.shortfalls && STATE.shortfalls.length) {
    const first = STATE.shortfalls[0]; const tot = Math.max(...STATE.shortfalls.map(s => s.deficit)); dangerCount++;
    items.push(`<div class="alert danger"><span class="icon">▼</span><div><strong>Necesidad de fondeo</strong> el ${fmtDate(first.date)}: faltarían <strong>${fmtARS.format(tot)}</strong>. ${STATE.shortfalls.length>1?`(${STATE.shortfalls.length} días con déficit)`:""}</div></div>`);
  }
  (STATE.surplus_windows||[]).forEach(w => {
    if (w.days < 2) return; successCount++;
    const sug = suggestInvestment(w.days, w.min_surplus);
    const extra = sug && sug.extra > 0 ? ` Sobre FCI ~<strong>${fmtARS.format(sug.extra)}</strong> extra.` : "";
    items.push(`<div class="alert success"><span class="icon">▲</span><div><strong>Excedente</strong> ${fmtDate(w.start)} a ${fmtDate(w.end)} (<strong>${w.days}d</strong>): <strong>${fmtARS.format(w.min_surplus)}</strong> → <strong>${sug.suggestion}</strong>.${extra}</div></div>`);
  });
  const today = todayISO();
  STATE.inversiones.filter(i => i.FECHA_VTO >= today && i.FECHA_VTO <= addDays(today,7)).forEach(inv => {
    infoCount++;
    items.push(`<div class="alert info"><span class="icon">●</span><div><strong>Vence ${escapeHtml(inv.TIPO)}</strong> el ${fmtDate(inv.FECHA_VTO)} por ${fmtARS.format(+inv.MONTO||0)}.</div></div>`);
  });
  STATE.cheques.filter(c => ACTIVE.includes(c.ESTADO) && c.FECHA_PAGO >= today && c.FECHA_PAGO <= addDays(today,3) && c.TIPO==="emitido").forEach(c => {
    warnCount++;
    items.push(`<div class="alert warn"><span class="icon">✎</span><div><strong>Cheque ${c.ESTADO==="en_proceso_deposito"?"en depósito":"emitido"}</strong> a ${escapeHtml(c.BENEFICIARIO||c.N_CHEQUE)} se debita el ${fmtDate(c.FECHA_PAGO)} por ${fmtARS.format(+c.IMPORTE||0)}.</div></div>`);
  });
  STATE.gastos.filter(x => x.ESTADO==="proyectado" && x.FECHA >= today && x.FECHA <= addDays(today,7)).sort((a,b) => (+b.MONTO||0)-(+a.MONTO||0)).slice(0,3).forEach(x => {
    warnCount++;
    items.push(`<div class="alert warn"><span class="icon">↓</span><div><strong>Gasto próximo</strong>: ${escapeHtml(x.CONCEPTO)} (${escapeHtml(x.METODO)}) el ${fmtDate(x.FECHA)} por ${fmtARS.format(+x.MONTO||0)}.</div></div>`);
  });
  if (!items.length) { items.push(`<div class="alert success"><span class="icon">✓</span><div>Sin alertas.</div></div>`); successCount++; }
  c.innerHTML = items.join("");
  const chips = [];
  if (dangerCount) chips.push(`<span class="badge danger">${dangerCount} crítica${dangerCount>1?"s":""}</span>`);
  if (warnCount) chips.push(`<span class="badge warn">${warnCount} aviso${warnCount>1?"s":""}</span>`);
  if (successCount && !dangerCount) chips.push(`<span class="badge success">${successCount} oportunidad${successCount>1?"es":""}</span>`);
  if (infoCount) chips.push(`<span class="badge info">${infoCount} info</span>`);
  if (!chips.length) chips.push(`<span class="badge success">todo OK</span>`);
  summary.innerHTML = chips.join(" ");
  if (dangerCount > 0) panel.classList.add("expanded");
}

function renderUpcoming() {
  const fromDate = document.getElementById("upcoming-from").value;
  const toDate = document.getElementById("upcoming-to").value;
  const typeF = document.getElementById("upcoming-type").value;
  const search = document.getElementById("upcoming-search").value.toLowerCase().trim();
  const rows = [];
  STATE.points30.forEach(p => p.events.forEach((ev,i) => rows.push({
    date:p.date, kind:ev.kind, type:ev.type, concept:ev.concept,
    amount:ev.sign*ev.amount, balance:p.balance, _ord:i
  })));
  let filtered = rows;
  if (fromDate) filtered = filtered.filter(r => r.date >= fromDate);
  if (toDate) filtered = filtered.filter(r => r.date <= toDate);
  if (typeF !== "all") {
    if (typeF === "ingresos") filtered = filtered.filter(r => r.amount > 0);
    else if (typeF === "egresos") filtered = filtered.filter(r => r.amount < 0);
    else filtered = filtered.filter(r => r.kind === typeF);
  }
  if (search) filtered = filtered.filter(r => (r.concept||"").toLowerCase().includes(search) || (r.type||"").toLowerCase().includes(search));
  // Ordenar por fecha y orden original dentro del dia
  filtered.sort((a,b) => a.date < b.date ? -1 : a.date > b.date ? 1 : a._ord - b._ord);
  document.getElementById("upcoming-count").textContent = `${filtered.length} eventos`;
  document.getElementById("upcoming-hint").textContent = (fromDate||toDate) ? `${fromDate?fmtDate(fromDate):"—"} a ${toDate?fmtDate(toDate):"—"}` : "próximos 30 días";
  // Totalizador del rango filtrado
  const tot_in = filtered.filter(r => r.amount > 0).reduce((s,r) => s+r.amount, 0);
  const tot_eg = filtered.filter(r => r.amount < 0).reduce((s,r) => s+r.amount, 0);
  const tot_nt = tot_in + tot_eg;
  document.getElementById("upcoming-totals").innerHTML =
    `<span style="color:var(--success)">+${fmtARS.format(tot_in)}</span>` +
    ` <span style="color:var(--muted)">·</span> ` +
    `<span style="color:var(--danger)">${fmtARS.format(tot_eg)}</span>` +
    ` <span style="color:var(--muted)">·</span> ` +
    `<span style="color:${tot_nt>=0?'var(--success)':'var(--danger)'};">Neto ${fmtARS.format(tot_nt)}</span>`;

  // ---- SALDO INICIAL: balance del día anterior al primer dia del rango ----
  // Si hay fromDate: tomamos el balance del último punto previo a fromDate.
  //                  Si no hay punto previo (fromDate <= primer punto), restamos
  //                  los movimientos del fromDate al balance de ese día.
  // Si no hay fromDate: usamos el balance del día anterior al primer evento.
  let saldoInicial = 0;
  let fechaInicial = null;
  if (filtered.length) {
    const firstD = fromDate || filtered[0].date;
    // Punto previo
    const prev = STATE.points30.filter(p => p.date < firstD)
                                .sort((a,b) => b.date.localeCompare(a.date))[0];
    if (prev) {
      saldoInicial = prev.balance;
      fechaInicial = prev.date;
    } else {
      // No hay punto previo: usar balance del primer dia del rango menos sus movimientos
      const sameDay = STATE.points30.find(p => p.date === firstD);
      if (sameDay) {
        const mov = sameDay.events.reduce((s,ev) => s + ev.sign*ev.amount, 0);
        saldoInicial = sameDay.balance - mov;
        fechaInicial = firstD; // representa el inicio del día (antes de movimientos)
      }
    }
  }

  // Acumular saldo evento por evento
  let acum = saldoInicial;
  filtered.forEach(r => { acum += r.amount; r._saldoAcum = acum; });

  const tbody = document.querySelector("#upcoming-table tbody");
  if (!filtered.length) { tbody.innerHTML = `<tr><td colspan="5" class="empty">Sin eventos.</td></tr>`; return; }
  // Fila destacada de saldo inicial
  const lblIni = fechaInicial
    ? `Saldo inicial al cierre ${fmtDate(fechaInicial)}`
    : `Saldo inicial`;
  let rowsHtml = `<tr style="background:#eef2ff;font-weight:600;">`
    + `<td>—</td>`
    + `<td><span class="chip" style="background:#dbe1ff;color:var(--primary);">SI</span></td>`
    + `<td>${lblIni}</td>`
    + `<td class="num" style="color:var(--muted);">—</td>`
    + `<td class="num" style="color:${saldoInicial>=0?'var(--primary)':'var(--danger)'};">${fmtARS.format(saldoInicial)}</td>`
    + `</tr>`;
  rowsHtml += filtered.map(r => {
    const cl = r.amount >= 0 ? "success" : "danger"; const sg = r.amount >= 0 ? "+" : "";
    const acColor = r._saldoAcum >= 0 ? "var(--primary)" : "var(--danger)";
    return `<tr><td>${fmtDate(r.date)}</td><td><span class="chip ${cl}">${escapeHtml(r.type)}</span></td><td>${escapeHtml(r.concept)}</td><td class="num" style="color:${r.amount>=0?'var(--success)':'var(--danger)'}">${sg}${fmtARS.format(r.amount)}</td><td class="num" style="color:${acColor};font-weight:600;">${fmtARS.format(r._saldoAcum)}</td></tr>`;
  }).join("");
  tbody.innerHTML = rowsHtml;
}
["upcoming-from","upcoming-to","upcoming-type","upcoming-search"].forEach(id => {
  document.getElementById(id).addEventListener("input", renderUpcoming);
  document.getElementById(id).addEventListener("change", renderUpcoming);
});
document.getElementById("btn-upcoming-reset").addEventListener("click", () => {
  document.getElementById("upcoming-from").value = "";
  document.getElementById("upcoming-to").value = "";
  document.getElementById("upcoming-type").value = "all";
  document.getElementById("upcoming-search").value = "";
  renderUpcoming();
});

/* ================== SIMULADOR DE FONDEO ================== */
function fmtNumAR(n) {
  if (n === null || n === undefined || n === "" || isNaN(n)) return "";
  return new Intl.NumberFormat("es-AR", {maximumFractionDigits:2}).format(+n);
}
function parseNumAR(s) {
  if (typeof s !== "string") return parseFloat(s) || 0;
  // Saca puntos de miles y deja coma decimal -> punto
  s = s.replace(/\./g, "").replace(",", ".").trim();
  return parseFloat(s) || 0;
}

const SIM_K_ING = "flujo_sim_ingresos";
const SIM_K_EXT = "flujo_sim_extras";
const SIM_K_FECHA = "flujo_sim_fecha";

function simReadList(key, def) {
  try { return JSON.parse(localStorage.getItem(key) || def); } catch(e) { return JSON.parse(def); }
}
function simSaveList(key, list) {
  try { localStorage.setItem(key, JSON.stringify(list)); } catch(e) {}
}

function simGetFechaHasta() {
  let v = document.getElementById("sim-fecha-hasta").value;
  if (!v) {
    v = localStorage.getItem(SIM_K_FECHA) || addDays(todayISO(), 30);
    document.getElementById("sim-fecha-hasta").value = v;
  }
  return v;
}

function simChequesAlDia(hasta) {
  // SOLO estado "pendiente" (Aceptado/Emitido). Los "en proceso de deposito"
  // ya estan camino al banco y se debitaron/estan por debitarse, no se cuentan.
  const sortedC = STATE.cheques.filter(c =>
    c.ESTADO === "pendiente" && c.TIPO === "emitido"
    && c.FECHA_PAGO && c.FECHA_PAGO <= hasta);
  const tot = sortedC.reduce((s,c) => s + (+c.IMPORTE || 0), 0);
  return { lista: sortedC, total: tot };
}
function simCarteraTotal() {
  return STATE.cheques.filter(c =>
    ACTIVE.includes(c.ESTADO) && c.TIPO === "recibido")
    .reduce((s,c) => s + (+c.IMPORTE || 0), 0);
}
function simSaldoMinimoEnRango(hasta) {
  const today = todayISO();
  const slice = STATE.points30.filter(p => p.date >= today && p.date <= hasta);
  if (!slice.length) return { val: null, fecha: null };
  let m = slice[0];
  slice.forEach(p => { if (p.balance < m.balance) m = p; });
  return { val: m.balance, fecha: m.date };
}

function simRenderTabla(tblId, key, ingreso) {
  const list = simReadList(key, "[]");
  const tbody = document.querySelector("#"+tblId+" tbody");
  if (!list.length) {
    tbody.innerHTML = `<tr><td colspan="3" class="muted" style="text-align:center;padding:10px;font-size:11.5px;">Sin filas. Click en "+ Agregar" para sumar ${ingreso?"un ingreso":"un recurso"}.</td></tr>`;
    return 0;
  }
  let tot = 0;
  tbody.innerHTML = list.map((r,i) => {
    tot += (+r.m || 0);
    return `<tr data-i="${i}">
      <td style="padding:3px 6px;"><input class="sim-c" data-k="${key}" data-i="${i}" type="text" value="${escapeHtml(r.c||"")}" placeholder="concepto" style="width:100%;border:1px solid var(--line);border-radius:5px;padding:4px 6px;font-size:12px;"></td>
      <td style="padding:3px 6px;text-align:right;"><input class="sim-m" data-k="${key}" data-i="${i}" type="text" inputmode="decimal" value="${fmtNumAR(r.m||0)}" style="width:140px;border:1px solid var(--line);border-radius:5px;padding:4px 6px;font-size:12px;text-align:right;"></td>
      <td style="padding:3px 0;width:24px;text-align:center;"><button class="sim-x" data-k="${key}" data-i="${i}" title="Eliminar" style="border:none;background:none;cursor:pointer;color:var(--danger);font-size:14px;">×</button></td>
    </tr>`;
  }).join("");
  return tot;
}

function renderSimulador() {
  const hasta = simGetFechaHasta();
  localStorage.setItem(SIM_K_FECHA, hasta);

  // Cheques al dia
  const chq = simChequesAlDia(hasta);
  document.getElementById("sim-cheques-total").textContent = "−" + fmtARS.format(chq.total);
  document.getElementById("sim-cheques-cant").textContent = `${chq.lista.length} cheques · al ${fmtDate(hasta)}`;

  // Ingresos
  const totIng = simRenderTabla("sim-ingresos-tbl", SIM_K_ING, true);
  document.getElementById("sim-ingresos-total").textContent = fmtARS.format(totIng);

  // Recursos adicionales
  const totExt = simRenderTabla("sim-extras-tbl", SIM_K_EXT, false);
  const cartera = simCarteraTotal();
  document.getElementById("sim-cartera-total").textContent = fmtARS.format(cartera);
  document.getElementById("sim-extras-total").textContent = fmtARS.format(cartera + totExt);

  // Necesidad de fondeo (sin extras)
  const fondeo = totIng - chq.total;  // negativo = falta plata
  const fondMonto = document.getElementById("sim-fondeo-monto");
  const fondBlock = document.getElementById("sim-fondeo-block");
  if (fondeo < 0) {
    fondMonto.textContent = fmtARS.format(fondeo);
    fondMonto.style.color = "var(--danger)";
    fondBlock.style.background = "#fff7f7";
    fondBlock.style.borderColor = "#f0c0c0";
    document.getElementById("sim-fondeo-desc").textContent = "Te falta esta plata para cubrir los cheques";
  } else {
    fondMonto.textContent = "+" + fmtARS.format(fondeo);
    fondMonto.style.color = "var(--success)";
    fondBlock.style.background = "#f3faf6";
    fondBlock.style.borderColor = "#bfe6cf";
    document.getElementById("sim-fondeo-desc").textContent = "Te sobra esta plata después de los cheques";
  }

  // Cobertura
  const cob = chq.total > 0 ? (totIng / chq.total * 100) : 0;
  document.getElementById("sim-cobertura").textContent = chq.total > 0 ? `${cob.toFixed(1)}%` : "—";

  // Saldo mínimo
  const sm = simSaldoMinimoEnRango(hasta);
  document.getElementById("sim-saldo-min").textContent = sm.val !== null
    ? `${fmtARS.format(sm.val)} (${fmtDate(sm.fecha)})`
    : "—";

  // Saldo final escenario = fondeo + cartera + extras
  const finalSaldo = fondeo + cartera + totExt;
  const finalEl = document.getElementById("sim-saldo-final");
  finalEl.textContent = (finalSaldo >= 0 ? "+" : "") + fmtARS.format(finalSaldo);
  finalEl.style.color = finalSaldo >= 0 ? "var(--success)" : "var(--danger)";
}

/* Handlers del simulador */
function simAddRow(key) {
  const list = simReadList(key, "[]");
  list.push({c:"", m:0});
  simSaveList(key, list);
  renderSimulador();
}
function simDelRow(key, i) {
  const list = simReadList(key, "[]");
  list.splice(i, 1);
  simSaveList(key, list);
  renderSimulador();
}
function simEditRow(key, i, field, val) {
  const list = simReadList(key, "[]");
  if (i >= list.length) return;
  if (field === "c") list[i].c = val;
  else if (field === "m") list[i].m = parseFloat(val) || 0;
  simSaveList(key, list);
}

document.getElementById("sim-fecha-hasta").addEventListener("change", renderSimulador);
document.getElementById("sim-btn-hoy").addEventListener("click", () => {
  document.getElementById("sim-fecha-hasta").value = addDays(todayISO(), 30);
  renderSimulador();
});
document.getElementById("sim-btn-fin-mes").addEventListener("click", () => {
  const t = new Date();
  const last = new Date(t.getFullYear(), t.getMonth()+1, 0);
  const iso = last.toISOString().slice(0,10);
  document.getElementById("sim-fecha-hasta").value = iso;
  renderSimulador();
});
document.getElementById("sim-add-ingreso").addEventListener("click", () => simAddRow(SIM_K_ING));
document.getElementById("sim-add-extra").addEventListener("click", () => simAddRow(SIM_K_EXT));
document.getElementById("sim-btn-reset").addEventListener("click", () => {
  if (!confirm("Resetear el simulador? Se borran los ingresos y extras que cargaste.")) return;
  localStorage.removeItem(SIM_K_ING);
  localStorage.removeItem(SIM_K_EXT);
  renderSimulador();
});
document.getElementById("sim-btn-copy").addEventListener("click", () => {
  const hasta = simGetFechaHasta();
  const chq = simChequesAlDia(hasta);
  const ing = simReadList(SIM_K_ING, "[]");
  const ext = simReadList(SIM_K_EXT, "[]");
  const totIng = ing.reduce((s,r) => s+(+r.m||0), 0);
  const cartera = simCarteraTotal();
  const totExt = ext.reduce((s,r) => s+(+r.m||0), 0);
  const fondeo = totIng - chq.total;
  const finalSaldo = fondeo + cartera + totExt;
  let txt = `ESCENARIO DE FONDEO - al ${fmtDate(hasta)}\n`;
  txt += `─────────────────────────────────\n`;
  txt += `Total Cheques    ${fmtARS.format(-chq.total)}\n\n`;
  ing.forEach(r => { txt += `${(r.c||"(sin concepto)").padEnd(20)} ${fmtARS.format(+r.m||0)}\n`; });
  txt += `\nTOTAL INGRESOS   ${fmtARS.format(totIng)}\n`;
  txt += `─────────────────────────────────\n`;
  txt += `NECESIDAD FONDEO ${fmtARS.format(fondeo)}\n\n`;
  ext.forEach(r => { txt += `${(r.c||"(sin concepto)").padEnd(20)} ${fmtARS.format(+r.m||0)}\n`; });
  txt += `CHEQUES EN CARTERA  ${fmtARS.format(cartera)}\n`;
  txt += `─────────────────────────────────\n`;
  txt += `SALDO FINAL      ${fmtARS.format(finalSaldo)}\n`;
  const ta = document.getElementById("sim-clipboard");
  ta.value = txt; ta.select(); document.execCommand("copy");
  alert("Escenario copiado al portapapeles. Pegalo donde quieras.");
});

// Eventos en las tablas editables del simulador
["sim-ingresos-tbl","sim-extras-tbl"].forEach(id => {
  const tbl = document.getElementById(id);
  tbl.addEventListener("input", ev => {
    const t = ev.target;
    if (t.classList.contains("sim-c")) {
      simEditRow(t.dataset.k, parseInt(t.dataset.i,10), "c", t.value);
    } else if (t.classList.contains("sim-m")) {
      // Permitir tipear sin perder foco. Parsear con formato AR.
      simEditRow(t.dataset.k, parseInt(t.dataset.i,10), "m",
                 parseNumAR(t.value));
    } else { return; }
    // SOLO recalculamos totales (no re-renderizamos tabla, asi no se pierde el foco)
    recalcSimulador();
  });
  // Al SALIR del input de monto, lo reformateamos con puntos de miles
  tbl.addEventListener("focusout", ev => {
    const t = ev.target;
    if (t.classList.contains("sim-m")) {
      t.value = fmtNumAR(parseNumAR(t.value));
    }
  });
  // Al ENTRAR (foco) en el input de monto, mostramos el numero "limpio" para editar
  tbl.addEventListener("focusin", ev => {
    const t = ev.target;
    if (t.classList.contains("sim-m")) {
      const v = parseNumAR(t.value);
      t.value = v ? String(v) : "";
      t.select();
    }
  });
  tbl.addEventListener("click", ev => {
    const b = ev.target.closest(".sim-x");
    if (b) simDelRow(b.dataset.k, parseInt(b.dataset.i,10));
  });
});

// Recalcula SOLO totales y KPIs, sin tocar las tablas (mantiene el foco)
function recalcSimulador() {
  const hasta = simGetFechaHasta();
  localStorage.setItem(SIM_K_FECHA, hasta);
  const chq = simChequesAlDia(hasta);
  const ingList = simReadList(SIM_K_ING, "[]");
  const extList = simReadList(SIM_K_EXT, "[]");
  const totIng = ingList.reduce((s,r) => s + (+r.m || 0), 0);
  const totExt = extList.reduce((s,r) => s + (+r.m || 0), 0);
  const cartera = simCarteraTotal();
  document.getElementById("sim-cheques-total").textContent = "−" + fmtARS.format(chq.total);
  document.getElementById("sim-cheques-cant").textContent = `${chq.lista.length} cheques · al ${fmtDate(hasta)}`;
  document.getElementById("sim-ingresos-total").textContent = fmtARS.format(totIng);
  document.getElementById("sim-cartera-total").textContent = fmtARS.format(cartera);
  document.getElementById("sim-extras-total").textContent = fmtARS.format(cartera + totExt);
  const fondeo = totIng - chq.total;
  const fondMonto = document.getElementById("sim-fondeo-monto");
  const fondBlock = document.getElementById("sim-fondeo-block");
  if (fondeo < 0) {
    fondMonto.textContent = fmtARS.format(fondeo);
    fondMonto.style.color = "var(--danger)";
    fondBlock.style.background = "#fff7f7";
    fondBlock.style.borderColor = "#f0c0c0";
    document.getElementById("sim-fondeo-desc").textContent = "Te falta esta plata para cubrir los cheques";
  } else {
    fondMonto.textContent = "+" + fmtARS.format(fondeo);
    fondMonto.style.color = "var(--success)";
    fondBlock.style.background = "#f3faf6";
    fondBlock.style.borderColor = "#bfe6cf";
    document.getElementById("sim-fondeo-desc").textContent = "Te sobra esta plata después de los cheques";
  }
  const cob = chq.total > 0 ? (totIng / chq.total * 100) : 0;
  document.getElementById("sim-cobertura").textContent = chq.total > 0 ? `${cob.toFixed(1)}%` : "—";
  const sm = simSaldoMinimoEnRango(hasta);
  document.getElementById("sim-saldo-min").textContent = sm.val !== null
    ? `${fmtARS.format(sm.val)} (${fmtDate(sm.fecha)})`
    : "—";
  const finalSaldo = fondeo + cartera + totExt;
  const finalEl = document.getElementById("sim-saldo-final");
  finalEl.textContent = (finalSaldo >= 0 ? "+" : "") + fmtARS.format(finalSaldo);
  finalEl.style.color = finalSaldo >= 0 ? "var(--success)" : "var(--danger)";
}

/* ============== FIN SIMULADOR ================ */

buildExpenseFilterOptions();
buildSaldoCuentas();
renderCheques();
renderGastos();
renderInversiones();
renderMovimientos();
renderSaldos();
renderDashboard();

/* ============================================================
   CASH FLOW TAB — versión simple
   ============================================================ */

// Estado del Cash Flow (mes seleccionado + entradas locales de la sesión)
const CF_STATE = {
  mes: null,
  ingresosLocales: [],  // {cliente, monto, fecha, id}
  chqProyLocales: [],   // {beneficiario, monto, fecha, id}
  nextId: 1,
  overrides: {},        // keyed by excel row index: {excluido, montoOvr, fechaOvr}
};

function cfMesISO(d) { return d.toISOString().slice(0,7); }  // "2026-09"
function cfMesLabel(d) {
  const MESES = ["Enero","Febrero","Marzo","Abril","Mayo","Junio",
                 "Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];
  return MESES[d.getMonth()] + " " + d.getFullYear();
}
function cfInMes(isoDate, mesDate) {
  if (!isoDate) return false;
  return isoDate.slice(0,7) === cfMesISO(mesDate);
}

function cfGetData() {
  const CF = STATE.cash_flow || {};
  const chqEmitidos = CF.cheques_futuros || [];
  const chqProy = CF_STATE.chqProyLocales.map(c=>({
    fecha: c.fecha, emitido_a: c.beneficiario, monto: c.monto, estado:"proyectado", n_cheque:""
  }));
  return {
    cheques: [...chqEmitidos, ...chqProy],
    chqEmitidos,
    chqProy,
    ingEst: (CF.ingresos_extras || [])
      .map((i, idx) => {
        const ovr = CF_STATE.overrides[idx] || {};
        if (ovr.excluido) return null;
        return {
          fecha: ovr.fechaOvr || i.fecha,
          descripcion: i.descripcion || i.cliente || "",
          monto: ovr.montoOvr != null ? ovr.montoOvr : i.monto,
          confirmado: true, notas: "", fuente: "excel"
        };
      })
      .filter(Boolean)
      .concat(CF_STATE.ingresosLocales.map(i=>({
        fecha: i.fecha, descripcion: i.cliente, monto: i.monto, confirmado: true,
        notas: "", fuente: "browser", _lid: i.id
      }))),
    ingReal: (CF.facturas || []).filter(f => f.cobrada && f.fecha_cobro),
  };
}

function cfBuildTimeline(mesDate) {
  const { cheques, ingEst, ingReal } = cfGetData();

  const primerDia = new Date(mesDate.getFullYear(), mesDate.getMonth(), 1);
  const ultimoDia = new Date(mesDate.getFullYear(), mesDate.getMonth()+1, 0);
  const primerISO = primerDia.toISOString().slice(0,10);
  const ultimoISO = ultimoDia.toISOString().slice(0,10);

  // Agrupar por semana lunes-domingo, pero cliqueada al mes actual
  const semanas = [];
  let cur = new Date(primerDia);
  // Retroceder al lunes de la primera semana del mes
  while (cur.getDay() !== 1) cur.setDate(cur.getDate() - 1);

  while (cur <= ultimoDia) {
    const ws = new Date(cur);
    const we = new Date(cur); we.setDate(we.getDate() + 6);
    const wsISO = ws.toISOString().slice(0,10);
    const weISO = we.toISOString().slice(0,10);

    // Clipear al rango del mes: solo días que caen dentro del mes visible
    const rangeFrom = wsISO < primerISO ? primerISO : wsISO;
    const rangeTo   = weISO > ultimoISO ? ultimoISO : weISO;

    // Si el rango clipeado no tiene días en el mes, saltar
    if (rangeFrom > ultimoISO || rangeTo < primerISO) {
      cur.setDate(cur.getDate()+7); continue;
    }

    // Filtrar eventos solo dentro del rango clipeado del mes
    const chqW  = cheques.filter(c=>c.fecha >= rangeFrom && c.fecha <= rangeTo);
    const estW  = ingEst.filter(i=>i.fecha >= rangeFrom && i.fecha <= rangeTo);
    const realW = ingReal.filter(i=>{
      const f = i.fecha_cobro || i.fecha; return f >= rangeFrom && f <= rangeTo;
    });

    // Label: muestra el rango clipeado para que quede claro cuántos días cubre
    const dFrom = new Date(rangeFrom + "T12:00:00");
    const dTo   = new Date(rangeTo   + "T12:00:00");
    const fmtD  = d => d.getDate().toString().padStart(2,'0') + "/" + (d.getMonth()+1).toString().padStart(2,'0');
    const label = rangeFrom === rangeTo ? fmtD(dFrom) : `${fmtD(dFrom)} – ${fmtD(dTo)}`;

    semanas.push({
      label,
      egr:     chqW.reduce((s,c)=>s+c.monto, 0),
      ingEst:  estW.reduce((s,i)=>s+i.monto, 0),
      ingReal: realW.reduce((s,i)=>s+(i.monto_efectivo||i.total||0), 0),
      chqW, estW, realW,
    });
    cur.setDate(cur.getDate()+7);
  }
  return semanas;
}

function cfRenderMes() {
  const mes = CF_STATE.mes;
  document.getElementById("cf-mes-label").textContent = cfMesLabel(mes);
  document.getElementById("cf-timeline-hint").textContent = cfMesLabel(mes);

  const { cheques, ingEst, ingReal } = cfGetData();
  const semanas = cfBuildTimeline(mes);
  const mesISO = cfMesISO(mes);

  // KPIs
  const totalEgr  = semanas.reduce((s,w)=>s+w.egr,0);
  const totalEst  = semanas.reduce((s,w)=>s+w.ingEst,0);
  const totalReal = semanas.reduce((s,w)=>s+w.ingReal,0);
  const bal = totalEst + totalReal - totalEgr;

  document.getElementById("cf-kpi-egr").textContent = fmtARS.format(totalEgr);
  document.getElementById("cf-kpi-ing-est").textContent = fmtARS.format(totalEst);
  document.getElementById("cf-kpi-ing-real").textContent = fmtARS.format(totalReal);
  const balEl = document.getElementById("cf-kpi-bal");
  balEl.textContent = (bal>=0?"+":"") + fmtARS.format(bal);
  balEl.style.color = bal>=0?"var(--success)":"var(--danger)";
  document.getElementById("cf-bal-card").className = "card " + (bal>=0?"success":"danger");

  // Timeline
  const tbody = document.getElementById("cf-tl-body");
  const tfoot = document.getElementById("cf-tl-foot");
  let acum = 0;
  tbody.innerHTML = semanas.map(w=>{
    const net = w.ingEst + w.ingReal - w.egr;
    acum += net;
    const netColor = net>=0?"var(--success)":"var(--danger)";
    const acumColor = acum>=0?"var(--success)":"var(--danger)";
    return `<tr>
      <td style="font-weight:600;">${w.label}</td>
      <td class="num" style="color:#c0392b;">${w.egr ? fmtARS.format(w.egr) : "<span class='muted'>—</span>"}</td>
      <td class="num" style="color:#0a8a5e;">${w.ingEst ? fmtARS.format(w.ingEst) : "<span class='muted'>—</span>"}</td>
      <td class="num" style="color:#1A2D9C;">${w.ingReal ? fmtARS.format(w.ingReal) : "<span class='muted'>—</span>"}</td>
      <td class="num" style="color:${netColor};font-weight:700;">${(net>=0?"+":"")}${fmtARS.format(net)}</td>
      <td class="num" style="color:${acumColor};font-weight:700;">${(acum>=0?"+":"")}${fmtARS.format(acum)}</td>
    </tr>`;
  }).join("");

  tfoot.innerHTML = `<tr style="background:var(--primary-soft);font-weight:700;">
    <td>TOTAL ${cfMesLabel(mes).toUpperCase()}</td>
    <td class="num" style="color:#c0392b;">${fmtARS.format(totalEgr)}</td>
    <td class="num" style="color:#0a8a5e;">${fmtARS.format(totalEst)}</td>
    <td class="num" style="color:#1A2D9C;">${fmtARS.format(totalReal)}</td>
    <td class="num" style="color:${bal>=0?"var(--success)":"var(--danger)"};">${(bal>=0?"+":"")}${fmtARS.format(bal)}</td>
    <td class="num" style="color:${bal>=0?"var(--success)":"var(--danger)"};">${(bal>=0?"+":"")}${fmtARS.format(bal)}</td>
  </tr>`;

  // Cheques emitidos del mes → 2 columnas por quincena
  const { chqEmitidos, chqProy } = cfGetData();
  const chqMes = chqEmitidos.filter(c=>c.fecha && c.fecha.slice(0,7)===mesISO)
                             .sort((a,b)=>a.fecha.localeCompare(b.fecha));
  const chq1 = chqMes.filter(c=>parseInt(c.fecha.slice(8,10))<=15);
  const chq2 = chqMes.filter(c=>parseInt(c.fecha.slice(8,10))>15);
  const renderChqHalf = (items, tbodyId, totalId) => {
    const tbody = document.querySelector(`#${tbodyId} tbody`);
    tbody.innerHTML = items.length ? items.map(c=>`<tr>
      <td style="white-space:nowrap;">${fmtDateShort(c.fecha)}</td>
      <td style="max-width:110px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escapeHtml(c.emitido_a)}">${escapeHtml(c.emitido_a)}</td>
      <td class="num" style="color:#c0392b;font-weight:600;">${fmtARS.format(c.monto)}</td>
    </tr>`).join("") : '<tr><td colspan="3" class="empty" style="font-size:11px;">Sin cheques</td></tr>';
    const total = items.reduce((s,c)=>s+c.monto,0);
    document.getElementById(totalId).textContent = total ? "Total: " + fmtARS.format(total) : "";
  };
  renderChqHalf(chq1, "cf-chq-1-15", "cf-chq-1-15-total");
  renderChqHalf(chq2, "cf-chq-16-fin", "cf-chq-16-fin-total");

  // Cheques proyectados (agregados en browser)
  const projTbl = document.querySelector("#cf-chq-proj-tbl tbody");
  const chqProjMes = chqProy.filter(c=>c.fecha && c.fecha.slice(0,7)===mesISO);
  projTbl.innerHTML = chqProjMes.length ? chqProjMes.map(c=>`<tr>
    <td>${escapeHtml(c.emitido_a)}</td>
    <td>${fmtDate(c.fecha)}</td>
    <td class="num" style="color:#c0392b;font-weight:600;">${fmtARS.format(c.monto)}</td>
    <td><button onclick="cfDeleteChqProy(${c._lid})" style="color:#c0392b;border:none;background:none;cursor:pointer;">✕</button></td>
  </tr>`).join("") : '<tr><td colspan="4" class="empty" style="font-size:11px;">Sin cheques proyectados agregados</td></tr>';

  // Tabla ingresos esperados (Excel + browser)
  cfRenderIngTable();

  // Ingresos reales del mes
  const realMes = ingReal.filter(f=>{
    const fc = f.fecha_cobro || f.fecha;
    return fc && fc.slice(0,7)===mesISO;
  }).sort((a,b)=>(a.fecha_cobro||a.fecha).localeCompare(b.fecha_cobro||b.fecha));
  const realTbl = document.querySelector("#cf-real-tbl tbody");
  realTbl.innerHTML = realMes.length ? realMes.map(f=>`<tr>
    <td>${fmtDate(f.fecha_cobro||f.fecha)}</td>
    <td>${escapeHtml(f.numero||"")}</td>
    <td>${escapeHtml(f.cliente)}</td>
    <td class="num" style="color:#1A2D9C;font-weight:600;">${fmtARS.format(f.monto_efectivo||f.total||0)}</td>
  </tr>`).join("") : '<tr><td colspan="4" class="empty">Sin ingresos reales registrados en este mes</td></tr>';
}

function cfRenderIngTable() {
  const mesISO = cfMesISO(CF_STATE.mes);
  const CF = STATE.cash_flow || {};

  // Filas de Excel con overrides aplicados
  const fromExcel = (CF.ingresos_extras || []).map((i, idx) => {
    const ovr = CF_STATE.overrides[idx] || {};
    return {
      cliente: i.descripcion || i.cliente || "",
      montoOrig: i.monto,
      fechaOrig: i.fecha,
      fecha: ovr.fechaOvr || i.fecha,
      monto: ovr.montoOvr != null ? ovr.montoOvr : i.monto,
      excluido: !!ovr.excluido,
      editado: !!(ovr.montoOvr != null || ovr.fechaOvr),
      idx
    };
  }).filter(r => r.fecha && r.fecha.slice(0,7) === mesISO);

  const fromBrowser = CF_STATE.ingresosLocales.filter(i=>i.fecha && i.fecha.slice(0,7)===mesISO);

  const excelRows = fromExcel.map(r => `<tr style="${r.excluido?'opacity:0.4;text-decoration:line-through;':''}">
    <td style="font-weight:600;">${escapeHtml(r.cliente)}</td>
    <td style="white-space:nowrap;">${fmtDate(r.fecha)}${r.editado&&(CF_STATE.overrides[r.idx]||{}).fechaOvr?' <span style="color:#e67e22;font-size:10px;">✎</span>':''}</td>
    <td class="num" style="color:#0a8a5e;font-weight:700;" title="Original: ${fmtARS.format(r.montoOrig)}">${fmtARS.format(r.monto)}${r.editado?' <span style="color:#e67e22;font-size:10px;">✎</span>':''}</td>
    <td><span class="chip" style="font-size:10px;">Excel</span>${r.editado?' <span class="chip warn" style="font-size:9px;">mod</span>':''}</td>
    <td style="white-space:nowrap;">${r.excluido
      ? `<button onclick="cfReactivarIng(${r.idx})" style="color:#0a8a5e;border:none;background:none;cursor:pointer;font-size:13px;" title="Reactivar">↩</button>`
      : `<button onclick="cfEditarIng(${r.idx})" style="color:#555;border:none;background:none;cursor:pointer;font-size:13px;" title="Editar monto/fecha">✏</button>
         <button onclick="cfExcluirIng(${r.idx})" style="color:#c0392b;border:none;background:none;cursor:pointer;font-size:13px;" title="Excluir del cálculo">✕</button>`
    }</td>
  </tr>`).join("");

  const browserRows = fromBrowser.map(r => `<tr>
    <td style="font-weight:600;">${escapeHtml(r.cliente)}</td>
    <td style="white-space:nowrap;">${fmtDate(r.fecha)}</td>
    <td class="num" style="color:#0a8a5e;font-weight:700;">${fmtARS.format(r.monto)}</td>
    <td><span class="chip warn" style="font-size:10px;">Sesión</span></td>
    <td><button onclick="cfDeleteIng(${r.id})" style="color:#c0392b;border:none;background:none;cursor:pointer;">✕</button></td>
  </tr>`).join("");

  const tbody = document.querySelector("#cf-ing-tbl tbody");
  tbody.innerHTML = (excelRows + browserRows) || '<tr><td colspan="5" class="empty" style="font-size:12px;">Sin ingresos para este mes. Agregá arriba o editá CASH_FLOW_MANUAL.xlsx</td></tr>';
}

function cfExcluirIng(idx) {
  CF_STATE.overrides[idx] = { ...(CF_STATE.overrides[idx]||{}), excluido: true };
  cfRenderMes();
}

function cfReactivarIng(idx) {
  if (CF_STATE.overrides[idx]) CF_STATE.overrides[idx].excluido = false;
  cfRenderMes();
}

function cfEditarIng(idx) {
  const CF = STATE.cash_flow || {};
  const orig = (CF.ingresos_extras || [])[idx];
  if (!orig) return;
  const ovr = CF_STATE.overrides[idx] || {};
  const curMonto = ovr.montoOvr != null ? ovr.montoOvr : orig.monto;
  const curFecha = ovr.fechaOvr || orig.fecha;
  const nuevoMonto = prompt("Monto para " + (orig.descripcion||orig.cliente||"") + ":\\n(actual: " + curMonto + ")", curMonto);
  if (nuevoMonto === null) return;
  const nuevaFecha = prompt("Fecha (AAAA-MM-DD):\\n(actual: " + curFecha + ")", curFecha);
  if (nuevaFecha === null) return;
  const m = parseFloat(nuevoMonto);
  if (!isNaN(m) && m > 0) {
    CF_STATE.overrides[idx] = {
      ...(CF_STATE.overrides[idx]||{}),
      montoOvr: m,
      fechaOvr: nuevaFecha && nuevaFecha.match(/^\\d{4}-\\d{2}-\\d{2}$/) ? nuevaFecha : curFecha
    };
    cfRenderMes();
  }
}

function cfDeleteIng(id) {
  CF_STATE.ingresosLocales = CF_STATE.ingresosLocales.filter(i=>i.id!==id);
  cfRenderMes();
}

function cfDeleteChqProy(id) {
  CF_STATE.chqProyLocales = CF_STATE.chqProyLocales.filter(c=>c.id!==id);
  cfRenderMes();
}

function renderCashFlow() {
  // Mes inicial: mes actual
  const hoy = new Date(STATE.today + "T12:00:00");
  CF_STATE.mes = new Date(hoy.getFullYear(), hoy.getMonth(), 1);

  // Navegación de meses
  document.getElementById("cf-mes-prev").onclick = () => {
    CF_STATE.mes = new Date(CF_STATE.mes.getFullYear(), CF_STATE.mes.getMonth()-1, 1);
    cfRenderMes();
  };
  document.getElementById("cf-mes-next").onclick = () => {
    CF_STATE.mes = new Date(CF_STATE.mes.getFullYear(), CF_STATE.mes.getMonth()+1, 1);
    cfRenderMes();
  };

  // Agregar ingreso
  document.getElementById("cf-ing-add").onclick = () => {
    const sel = document.getElementById("cf-ing-cliente").value;
    const nombre = document.getElementById("cf-ing-nombre").value.trim();
    const cliente = sel === "OTRO" ? (nombre || "Otro") : sel;
    const monto = parseFloat(document.getElementById("cf-ing-monto").value);
    const fecha = document.getElementById("cf-ing-fecha").value;
    if (!fecha || !monto || monto <= 0) {
      alert("Completá fecha y monto.");
      return;
    }
    CF_STATE.ingresosLocales.push({ cliente, monto, fecha, id: CF_STATE.nextId++ });
    document.getElementById("cf-ing-monto").value = "";
    document.getElementById("cf-ing-nombre").value = "";
    cfRenderMes();
  };

  // Agregar cheque proyectado
  document.getElementById("cf-chq-add").onclick = () => {
    const benef = document.getElementById("cf-chq-benef").value.trim();
    const monto = parseFloat(document.getElementById("cf-chq-monto").value);
    const fecha = document.getElementById("cf-chq-fecha").value;
    if (!benef || !fecha || !monto || monto <= 0) { alert("Completá beneficiario, monto y fecha."); return; }
    const newId = CF_STATE.nextId++;
    CF_STATE.chqProyLocales.push({ beneficiario: benef, monto, fecha, id: newId, _lid: newId });
    document.getElementById("cf-chq-monto").value = "";
    document.getElementById("cf-chq-benef").value = "";
    cfRenderMes();
  };

  // Descargar CSV
  document.getElementById("cf-ing-download").onclick = () => {
    if (!CF_STATE.ingresosLocales.length) { alert("No hay ingresos cargados en esta sesión para descargar."); return; }
    const lines = ["Cliente,Fecha,Monto,Notas"];
    CF_STATE.ingresosLocales.forEach(i => {
      lines.push(`"${i.cliente}","${i.fecha}","${i.monto}","Cargado en tablero"`);
    });
    const blob = new Blob([lines.join("\n")], {type:"text/csv;charset=utf-8;"});
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "ingresos_cashflow_" + cfMesISO(CF_STATE.mes) + ".csv";
    a.click();
  };

  // Setear fecha del input al primer día del mes visible
  const setFechaDefault = () => {
    const m = CF_STATE.mes;
    document.getElementById("cf-ing-fecha").value =
      m.getFullYear() + "-" + String(m.getMonth()+1).padStart(2,"0") + "-01";
  };
  document.getElementById("cf-mes-prev").addEventListener("click", setFechaDefault);
  document.getElementById("cf-mes-next").addEventListener("click", setFechaDefault);

  setFechaDefault();
  cfRenderMes();
}

renderCashFlow();
</script>
</body>
</html>